import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Dkj3JE0_.js";const u=JSON.parse('{"title":"seanpnex.github.io","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),i={name:"README.md"};function d(n,e,r,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="seanpnex-github-io" tabindex="-1">seanpnex.github.io <a class="header-anchor" href="#seanpnex-github-io" aria-label="Permalink to &quot;seanpnex.github.io&quot;">​</a></h1><p>Sean Guo&#39;s personal site and public learning base, built with <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> and deployed to GitHub Pages at <strong><a href="https://seanpnex.github.io" target="_blank" rel="noreferrer">seanpnex.github.io</a></strong>.</p><p>It hosts research projects plus evolving study notes for CFA Level II, JLPT N2, and Business German, available in English, 简体中文, 日本語, and Français.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>index.md</code></td><td>Home page</td></tr><tr><td><code>projects/</code></td><td>Research and project write-ups (NCCP, TTS chatbot, rivalry network, Wilson–Cowan equation)</td></tr><tr><td><code>blogs/</code></td><td>Learning base: <code>CFA/</code>, <code>JLPT-N2/</code>, <code>German/</code>, <code>coding_notes/</code></td></tr><tr><td><code>zh/</code>, <code>jp/</code>, <code>fr/</code></td><td>Translated pages, mirroring the English layout</td></tr><tr><td><code>public/charts/</code></td><td>Standalone interactive HTML charts embedded in notes via <code>&lt;iframe&gt;</code></td></tr><tr><td><code>public/flashcards/</code></td><td>Standalone flashcard decks built from CFA quizzes</td></tr><tr><td><code>public/</code></td><td>PDFs, images, and other static assets served as-is</td></tr><tr><td><code>.vitepress/</code></td><td>Site config, auto-generated sidebar, and custom theme</td></tr></tbody></table><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><p>Requires Node.js 18+ (CI uses Node 20).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> install</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:dev</span></span></code></pre></div><p>The dev server runs at <code>localhost:5173</code>. To check a production build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:build</span><span style="--shiki-light:#212121;--shiki-dark:#BBBBBB;"> &amp;&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:preview</span></span></code></pre></div><h2 id="writing-notes" tabindex="-1">Writing notes <a class="header-anchor" href="#writing-notes" aria-label="Permalink to &quot;Writing notes&quot;">​</a></h2><p>The sidebar is generated from the folder tree by <a href=".vitepress/auto-sidebar.mjs"><code>.vitepress/auto-sidebar.mjs</code></a>, so adding a note is just adding a Markdown file.</p><ul><li><strong>Ordering</strong> — files and folders sort by name; a prefix like <code>C2 </code> or <code>M1 </code> sets the order and is stripped from the label. Set <code>order:</code> in frontmatter to override.</li><li><strong>Labels</strong> — <code>title:</code> in frontmatter sets the sidebar text. Curriculum folder names map to readable labels via <code>GROUP_LABELS</code> in <code>auto-sidebar.mjs</code> (translations live in <code>topics.mjs</code>).</li><li><strong>Publishing</strong> — empty notes and notes with <code>draft: true</code> stay in the repo but are excluded from the build. Short notes (under ~1,500 characters) are published as outlines.</li><li><strong>Prev / next</strong> — page sequence follows the sidebar, and each learning track has its own sidebar so navigation stays inside the track.</li><li><strong>Math and diagrams</strong> — LaTeX math (<code>$…$</code>, <code>$$…$$</code>) and <code>```mermaid</code> blocks are supported.</li></ul><h3 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h3><p>Charts in <code>public/charts/</code> are self-contained HTML pages. Notes embed them with an iframe, adding <code>?lang=zh|ja|fr</code> for translated pages; each chart registers its own strings with <a href="public/charts/i18n.js"><code>i18n.js</code></a>. Charts report their rendered height to the host page, so the iframe resizes itself. The hairline curve charts share drawing helpers in <a href="public/charts/curve-kit.js"><code>curve-kit.js</code></a>.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>Locales are configured in <a href=".vitepress/config.mjs"><code>.vitepress/config.mjs</code></a> (<code>LOCALE_TEXT</code> holds the interface strings). Translated pages live under <code>/zh/</code>, <code>/jp/</code>, and <code>/fr/</code>. Learning notes are written in English first; when the language menu points to a translation that doesn&#39;t exist yet, it opens the English page instead of a 404.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>Pushing to <code>main</code> triggers <a href=".github/workflows/deploy.yml"><code>.github/workflows/deploy.yml</code></a>, which builds the site and publishes <code>.vitepress/dist</code> to the <code>gh-pages</code> branch. A second workflow, <a href=".github/workflows/commit_log.yml"><code>commit_log.yml</code></a>, appends each push to <code>workflow.log</code> and commits it back, so pull before pushing.</p><h2 id="fork-it-and-make-it-your-own" tabindex="-1">Fork it and make it your own <a class="header-anchor" href="#fork-it-and-make-it-your-own" aria-label="Permalink to &quot;Fork it and make it your own&quot;">​</a></h2><p>The site&#39;s code is free to reuse under GPL-3.0. The notes, projects, and personal details are Sean&#39;s, so replace them with your own.</p><h3 id="_1-fork-and-set-up-github-pages" tabindex="-1">1. Fork and set up GitHub Pages <a class="header-anchor" href="#_1-fork-and-set-up-github-pages" aria-label="Permalink to &quot;1. Fork and set up GitHub Pages&quot;">​</a></h3><ol><li>Fork this repo. To serve it at <code>https://&lt;your-username&gt;.github.io</code>, name your fork <code>&lt;your-username&gt;.github.io</code>.</li><li>In your fork, open <strong>Settings → Actions → General → Workflow permissions</strong>, select <strong>Read and write permissions</strong>, and save. The deploy workflow needs this to push the <code>gh-pages</code> branch.</li><li>Push any commit to <code>main</code>, or re-run the <strong>Deploy</strong> workflow from the <strong>Actions</strong> tab. When it finishes, a <code>gh-pages</code> branch exists.</li><li>Open <strong>Settings → Pages</strong>, set <strong>Source</strong> to <strong>Deploy from a branch</strong>, then select <code>gh-pages</code> and <code>/ (root)</code>. Your site goes live a minute later.</li></ol><p>If you keep a different repo name, the site is served at <code>https://&lt;your-username&gt;.github.io/&lt;repo&gt;/</code>. In that case, set <code>base: &quot;/&lt;repo&gt;/&quot;</code> in <code>.vitepress/config.mjs</code>. VitePress adds the base to Markdown links automatically, but not to raw HTML, so you also need to prefix the absolute <code>href</code> and <code>src</code> paths in HTML blocks. That includes <code>&lt;iframe&gt;</code> chart embeds, the home page, and the directory cards in <code>blogs/0-start.md</code>.</p><h3 id="_2-clone-and-run-it" tabindex="-1">2. Clone and run it <a class="header-anchor" href="#_2-clone-and-run-it" aria-label="Permalink to &quot;2. Clone and run it&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> clone</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> https://github.com/</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;">your-usernam</span><span style="--shiki-light:#24292EFF;--shiki-dark:#B392F0;">e</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;">/</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;">your-rep</span><span style="--shiki-light:#24292EFF;--shiki-dark:#B392F0;">o</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;">.git</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cd</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;">your-rep</span><span style="--shiki-light:#24292EFF;--shiki-dark:#B392F0;">o</span><span style="--shiki-light:#D32F2F;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#212121;--shiki-dark:#BBBBBB;"> &amp;&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> install</span><span style="--shiki-light:#212121;--shiki-dark:#BBBBBB;"> &amp;&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> run</span><span style="--shiki-light:#2B5581;--shiki-dark:#9DB1C5;"> docs:dev</span></span></code></pre></div><h3 id="_3-replace-sean-s-content" tabindex="-1">3. Replace Sean&#39;s content <a class="header-anchor" href="#_3-replace-sean-s-content" aria-label="Permalink to &quot;3. Replace Sean&#39;s content&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>What to change</th></tr></thead><tbody><tr><td><code>index.md</code></td><td>Your name, tagline, and portrait (it uses a GitHub avatar URL), plus the project cards and learning-track cards</td></tr><tr><td><code>.vitepress/config.mjs</code></td><td><code>title</code>, <code>description</code>, <code>nav</code>, <code>socialLinks</code>, <code>footer</code>, and the per-language strings in <code>LOCALE_TEXT</code></td></tr><tr><td><code>projects/</code>, <code>blogs/</code></td><td>Delete Sean&#39;s pages and add your own. The sidebar updates automatically</td></tr><tr><td><code>zh/</code>, <code>jp/</code>, <code>fr/</code></td><td>Translations. Delete the locales you don&#39;t need, and remove them from <code>locales</code> in <code>config.mjs</code></td></tr><tr><td><code>public/</code></td><td>Images, PDFs, <code>favicon.ico</code>, charts, and flashcards</td></tr><tr><td><code>coverletters/</code>, <code>workflow.log</code>, <code>index.md.bak</code></td><td>Sean&#39;s personal files. Delete them</td></tr><tr><td><code>.github/workflows/commit_log.yml</code></td><td>Optional push log. Delete it if you don&#39;t want a bot commit after every push</td></tr></tbody></table><p>The home page and the Learning Base page read the CFA folder through <code>.vitepress/theme/notes.data.js</code>. If you remove <code>blogs/CFA/</code>, update <code>notes.data.js</code> and the CFA card in <code>index.md</code> too, or the build fails.</p><h3 id="_4-edit-check-publish" tabindex="-1">4. Edit, check, publish <a class="header-anchor" href="#_4-edit-check-publish" aria-label="Permalink to &quot;4. Edit, check, publish&quot;">​</a></h3><ol><li>Add or edit Markdown files while <code>npm run docs:dev</code> is running. The page reloads as you save.</li><li>Run <code>npm run docs:build</code> before pushing. The build fails on dead links, and the deploy uses the same command.</li><li>Commit and push to <code>main</code>. The site redeploys automatically.</li></ol><p>To suggest a fix to this site itself, push a branch to your fork and open a pull request against <code>SEANPNEX/seanpnex.github.io</code>.</p><h2 id="for-ai-coding-agents" tabindex="-1">For AI coding agents <a class="header-anchor" href="#for-ai-coding-agents" aria-label="Permalink to &quot;For AI coding agents&quot;">​</a></h2><p>If you are an agent working in this repo or a fork of it, follow these rules.</p><p><strong>Commands</strong></p><ul><li>Install: <code>npm install</code>. Preview: <code>npm run docs:dev</code> (port 5173). Verify: <code>npm run docs:build</code>.</li><li>A task is done only when <code>npm run docs:build</code> exits 0. Read the build output, because dead links appear as <code>(!) Found dead link</code> before the failure.</li></ul><p><strong>How the site is built</strong></p><ul><li>Every <code>.md</code> file in the repo becomes a page, including this README. A link to a file that doesn&#39;t exist fails the build. In README, write the dev URL as plain code instead of a link, and link the license by its full GitHub URL.</li><li>Markdown is compiled as a Vue template. Literal double curly braces in prose are evaluated as Vue expressions, so put them in code spans or code blocks.</li><li>Math is enabled, so <code>$…$</code> in prose renders as LaTeX. Escape literal currency as <code>\\$</code>.</li><li>Never hand-write sidebar entries. <code>.vitepress/auto-sidebar.mjs</code> builds them from the folder tree. Control the result with file and folder names (an <code>M1 </code> or <code>C2 </code> prefix sets the order) and with the <code>title:</code>, <code>order:</code>, and <code>draft: true</code> frontmatter fields.</li><li>An empty note is a planned placeholder and is not published. Don&#39;t delete empty notes, and don&#39;t fill them with filler text.</li><li>When you add a curriculum folder, add its label to <code>GROUP_LABELS</code> in <code>.vitepress/auto-sidebar.mjs</code>, and add a translation for each locale in <code>.vitepress/topics.mjs</code>.</li></ul><p><strong>Translations</strong></p><ul><li>A translated page mirrors the English path under <code>zh/</code>, <code>jp/</code>, or <code>fr/</code>. Example: <code>blogs/CFA/C2 Economics/M1 Currency Exchange Rates.md</code> becomes <code>zh/blogs/CFA/C2 Economics/M1 Currency Exchange Rates.md</code>.</li><li>The Japanese folder is <code>jp</code>, but the language code is <code>ja</code>. Use <code>ja</code> for chart <code>?lang=</code> parameters and for <code>TOPIC_LABELS</code>.</li><li>Leave a translation missing rather than machine-filling a placeholder page, because the language menu already falls back to English.</li></ul><p><strong>Charts</strong></p><ul><li>A chart is one self-contained HTML file in <code>public/charts/</code>. Embed it with an <code>&lt;iframe&gt;</code> whose <code>src</code> is an absolute path like <code>/charts/name.html</code>, and give it a <code>title</code>. Copy an existing embed as a template.</li><li>On translated pages, add <code>?lang=zh|ja|fr</code> to the <code>src</code>, and register the chart&#39;s strings with <code>chartI18n.use(…)</code> from <code>public/charts/i18n.js</code>.</li><li>Charts must post their height to the parent page so the iframe can resize: <code>parent.postMessage({ chartHeight }, location.origin)</code>. Curve charts get this for free from <code>public/charts/curve-kit.js</code>.</li><li>Prefer plain SVG or the shared local scripts. If a chart needs a library, load it from a CDN with a pinned version, as the ECharts chart does.</li></ul><p><strong>Git</strong></p><ul><li>Run <code>git pull</code> before <code>git push</code>, because the <code>commit_log</code> workflow adds a commit after every push.</li><li>Commit message style is <code>&lt;Track&gt; &lt;module&gt;: &lt;change&gt;</code>, for example <code>CFA C2 M2: add saving-rate shift chart</code> or <code>JLPT: add Nでございます note</code>.</li><li>Never commit <code>node_modules/</code>, <code>.vitepress/dist/</code>, <code>.vitepress/cache/</code>, <code>.claude/</code>, or <code>.docx</code> files. Never edit <code>workflow.log</code> or the <code>gh-pages</code> branch by hand.</li><li>Ask before deleting or rewriting someone&#39;s existing notes. They are personal study material, not generated output.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><a href="https://github.com/SEANPNEX/seanpnex.github.io/blob/main/LICENSE" target="_blank" rel="noreferrer">GPL-3.0</a></p>',48)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
